<!doctype html><html><head><meta charset="utf-8"><title>Stock Inventory Report</title><style>body{font-family:Arial;font-size:12px;margin:24px}h1,h2{margin:0 0 8px}h2{margin-top:24px}table{width:100%;border-collapse:collapse}th,td{border:1px solid #bbb;padding:5px;text-align:left}th{background:#eee}.no-print{margin-bottom:12px}@media print{.no-print{display:none}}</style></head><body><button class="no-print" onclick="window.print()">Print</button><h1>Stock Inventory Report</h1><p>Period: {{$from}} to {{$to}} | Generated: {{now()->format('Y-m-d H:i')}}</p><h2>Products</h2><table><tr><th>SKU</th><th>Product</th><th>Qty</th><th>Reorder</th><th>Cost</th><th>Status</th></tr>@foreach($products as $p)<tr><td>{{$p->sku}}</td><td>{{$p->name}}</td><td>{{$p->quantity}} {{$p->unit}}</td><td>{{$p->reorder_level}}</td><td>{{$p->unit_cost}}</td><td>{{$p->status}}</td></tr>@endforeach</table><h2>Movements</h2><table><tr><th>Date</th><th>Product</th><th>Type</th><th>Qty</th><th>Reference</th><th>Source</th><th>Destination</th></tr>@foreach($movements as $m)<tr><td>{{$m->created_at->format('Y-m-d H:i')}}</td><td>{{$m->product->name??''}}</td><td>{{$m->movement_type}}</td><td>{{$m->quantity}}</td><td>{{$m->reference}}</td><td>{{$m->source}}</td><td>{{$m->destination}}</td></tr>@endforeach</table><h2>Network Assets</h2><table><tr><th>Type</th><th>Asset Tag</th><th>Serial</th><th>MAC</th><th>Status</th><th>Location</th></tr>@foreach($assets as $a)<tr><td>{{$a->asset_type}}</td><td>{{$a->asset_tag}}</td><td>{{$a->serial_no}}</td><td>{{$a->mac_address}}</td><td>{{$a->status}}</td><td>{{$a->location}}</td></tr>@endforeach</table><h2>Warranty</h2><table><tr><th>Product</th><th>Serial</th><th>MAC</th><th>Vendor</th><th>End</th><th>Status</th></tr>@foreach($warranties as $w)<tr><td>{{$w->product->name??''}}</td><td>{{$w->asset_serial}}</td><td>{{$w->asset_mac}}</td><td>{{$w->vendor}}</td><td>{{$w->warranty_end}}</td><td>{{$w->status}}</td></tr>@endforeach</table><h2>Lost / Damaged</h2><table><tr><th>Date</th><th>Product</th><th>Type</th><th>Qty</th><th>Status</th><th>Reason</th></tr>@foreach($damageRecords as $d)<tr><td>{{$d->incident_date}}</td><td>{{$d->product->name??''}}</td><td>{{$d->record_type}}</td><td>{{$d->quantity}}</td><td>{{$d->status}}</td><td>{{$d->reason}}</td></tr>@endforeach</table></body></html>